          environmentBulkActionMenuCloseTimerRef.current = window.setTimeout(() => {
            environmentBulkActionMenuCloseTimerRef.current = null;
            setEnvironmentBulkActionMenuClosing(false);
            setEnvironmentBulkActionMenuState(null);
          }, 90);
