          const normalizedModelId = getSkillDeepResearchModelMeta(nextModelId)?.id || PLAYGROUND_AGENT_DEEP_RESEARCH_MODEL_OPTIONS[0].id;
          const currentConfig = readDemoSettingsPlatformConfig();
